item(d,21,'Một nhóm muốn giữ raw data để có thể thay chunking và transform lại mà không lấy lại từ nguồn. Kiểu pipeline nào đáp ứng trực tiếp?', ['ELT: load raw trước rồi transform trong kho','ETL: chỉ load kết quả transform, không giữ bản gốc','Full refresh vào bảng cuối, ghi đè raw sau mỗi lần chạy'],'a','Giữ raw trước transform tạo khả năng tái xử lý từ bản gốc khi logic thay đổi.',kind='scenario',context='Nguồn lớn, còn logic chuẩn bị corpus có thể đổi qua nhiều lần eval.')
item(d,26,'CDC giảm chi phí đồng bộ bảng lớn bằng cách nào?', ['Chỉ lấy phần insert/update/delete đã thay đổi','Quét lại toàn bộ bảng nhưng giảm số cột hiển thị','Bỏ mọi delete event và chỉ lấy insert mới'],'a','CDC theo dõi thay đổi thay vì đọc lại toàn dataset ở mỗi lần sync.')
item(d,31,'Record có timestamp cũ nhưng tới pipeline muộn có thể bị watermark làm bỏ sót vì sao?', ['Record rơi sau ranh giới đã chốt dù thực tế chưa được ingest','Watermark luôn theo thời điểm pipeline nhận record nên không thể bỏ sót','Watermark tự làm mọi record có timestamp khác nhau thành duplicate'],'a','Ranh giới dựa timestamp/offset cần thiết kế cho late arrival; timestamp cũ không đồng nghĩa đã xử lý.')
item(d,35,'Hai chuỗi tiếng Việt nhìn giống nhau nhưng exact-match/dedup khác kết quả. Bước transform nào xử lý nguyên nhân Unicode?', ['Chuẩn hóa về cùng dạng như NFC trước khi so sánh/index','Chỉ tăng top-k để che lỗi exact matching','Giữ nguyên bytes khác nhau và coi là hai chính sách độc lập'],'a','NFC/NFD có thể hiển thị giống nhưng khác bytes; normalization đưa về cùng biểu diễn.')
item(d,37,'Unit test và data test của transformation khác nhau ở đối tượng được kiểm tra thế nào?', ['Unit test kiểm logic với fixture; data test kiểm dữ liệu thật sau materialize','Unit test chỉ kiểm production rows; data test chỉ kiểm SQL trên fixture','Cả hai chỉ kiểm tên bảng có tồn tại, không xét logic hoặc dữ liệu'],'a','Fixture input→expected output kiểm logic; assertions trên warehouse kiểm sức khỏe dữ liệu thực.')
item(d,47,'Dual-index cutover cho phép thay phiên bản corpus an toàn hơn bằng cơ chế nào?', ['Build/validate index mới song song rồi chuyển traffic đọc','Ghi đè index đang phục vụ và kiểm tra sau khi chuyển toàn traffic','Đưa query vào cả hai index rồi trộn vectors mà không phân version'],'a','Blue-green cho data giữ đường phục vụ cũ trong khi kiểm chứng index mới.')
item(d,50,'Vì sao nên profiling dữ liệu trước khi viết quality assertions?', ['Để biết phân bố/null/cardinality thật, tránh rule dựa trên phỏng đoán','Để chọn rule theo ví dụ nhỏ và xem mọi giá trị khác đều là lỗi','Để thay mọi assertions bằng một báo cáo thống kê không có hành động'],'a','Rule đoán sai có thể báo lỗi cho giá trị hợp lệ hoặc bỏ qua đúng failure mode quan trọng.')
item(d,55,'Trade-off giữa quality gate sớm và muộn là gì?', ['Sớm tiết kiệm compute nhưng ít context; muộn tốn hơn nhưng bắt được lỗi cần đủ ngữ cảnh','Gate sớm luôn biết đủ xung đột giữa mọi tài liệu; gate muộn chỉ kiểm format','Gate muộn luôn rẻ hơn vì đã embed nên không cần kiểm dữ liệu nữa'],'a','Vị trí gate cần cân bằng chi phí xử lý với thông tin có sẵn để nhận diện lỗi.')
item(d,56,'Một lỗi quality ở policy pháp lý khiến phiên bản mới chưa đáng tin, trong khi bản cũ vẫn đúng cho phạm vi đang phục vụ. Fail-closed nên làm gì?', ['Dừng cập nhật index và tiếp tục phục vụ bản cũ phù hợp','Log lỗi nhưng vẫn publish bản mới như bình thường','Xóa index cũ ngay để buộc agent dùng bản chưa đạt gate'],'a','Fail-closed chặn dữ liệu mới không đạt kiểm tra; lựa chọn cần xét hậu quả stale so với sai.',kind='scenario',context='Nhóm đã xác định stale có kiểm soát ít hại hơn công bố nội dung pháp lý sai.')
item(d,58,'Những thành phần nào cần có trong data contract? (Chọn tất cả đáp án đúng.)',['Schema và semantics của fields','SLA cùng ownership khi vi phạm','Chỉ tên bảng và định dạng file là đủ thay mọi cam kết','Chỉ query mẫu nhưng không xác định ý nghĩa field'],['a','b'],'Hợp đồng phải mô tả cấu trúc, nghĩa, mức phục vụ và trách nhiệm giữa producer/consumer.',kind='multiple_choice')
item(d,71,'Dataset cập nhật đúng lịch nhưng các hàng đều rỗng có thể vẫn pass freshness SLI. Điều này cho thấy gì?', ['Freshness đo thời điểm cập nhật, không tự chứng minh correctness/completeness','Freshness đồng nghĩa mọi content đã được validate','Có update timestamp mới là đủ bỏ qua các quality checks'],'a','On-time và nội dung đúng là hai trục khác nhau, cần kết hợp freshness với quality.')
item(d,78,'Vì sao thêm một cột metadata mới có thể là schema drift khó phát hiện hơn xóa cột đang được dùng?', ['Downstream chưa tham chiếu cột mới nên không crash, cần schema-diff chủ động','Mọi cột mới đều gây exception trước khi ingest','Chỉ cột bị xóa mới có khả năng làm lộ dữ liệu trong corpus'],'a','Cột mới có thể lặng lẽ đi vào index dù chưa có assertions cho field đó.')
item(d,79,'Một detector báo quá nhiều false positive có thể làm regression thật bị bỏ qua qua cơ chế nào?', ['Đội ngũ mất niềm tin và ngừng phản hồi kênh cảnh báo','Mọi false positive tự tăng độ chính xác của detector ở lượt sau','Nhiều cảnh báo bảo đảm mọi người kiểm tra kỹ hơn từng cảnh báo'],'a','Alert fatigue tiêu hao chú ý và huấn luyện hành vi bỏ qua kênh quan trọng.')
item(d,81,'Column-level lineage bổ sung điều gì so với table-level lineage?', ['Theo dõi field cụ thể ảnh hưởng field nào downstream','Chỉ liệt kê job nào phụ thuộc job nào','Chỉ ghi timestamp lần cập nhật cuối của toàn bảng'],'a','Table lineage cho phụ thuộc bảng/job; column lineage cho impact analysis ở cấp field.')
item(d,92,'Khi vi phạm SLA cứng đang ảnh hưởng ngay tới câu trả lời production, mức alert nào phù hợp hơn dashboard định kỳ?', ['Page người trực và route tới owner dataset','Chỉ tạo dashboard entry để review cuối tháng','Chỉ log ở pipeline, không route vì agent vẫn trả câu trả lời'],'a','Severity theo tác động hiện tại; ownership quyết định đội chịu trách nhiệm phản ứng.')
item(d,93,'Sau khi sửa root cause của data incident, điều kiện nào cần trước khi mở lại phục vụ bình thường?', ['Verify bằng cách chạy lại quality gate','Chỉ kiểm source code đã được merge','Chỉ thấy job chạy xanh, không đối chiếu data/output'],'a','Fix chưa đủ; quality gate phải xác minh dữ liệu đã đạt điều kiện trước khi mở lại.')
item(d,103,'Những lựa chọn nào giúp retry/backfill tránh làm nhân đôi dữ liệu? (Chọn tất cả đáp án đúng.)',['Upsert/idempotent writes thay insert lặp','Đọc/ghi partition cụ thể cho lần chạy','Mỗi retry dùng dữ liệu latest theo thời điểm hiện tại','Coi scheduler retry là bảo đảm exactly-once với mọi hệ ngoài'],['a','b'],'Task có thể được chạy lại; tính xác định và idempotency giữ retry không tạo duplicate hoặc đổi tập input.',kind='multiple_choice')
