item(d,30,'Defense in depth giữa input, LLM và output rails đem lại lợi ích gì?', ['Các lớp bắt các lỗi khác nhau, lớp sau có thể chặn lỗi lớp trước bỏ sót','Một input classifier tốt cho phép bỏ output checks','Các lớp chỉ nhân bản cùng một regex để tăng số lần kiểm tra'],'a','Tách lớp theo bề mặt rủi ro bổ sung bảo vệ thay vì giả định một detector hoàn hảo.')
item(d,34,'Một HR assistant từ chối tư vấn crypto đang áp dụng kiểm soát nào?', ['Topic filtering theo phạm vi use case','Format validation của output JSON','Grounding check đối chiếu từng factual claim'],'a','Topic filter giới hạn chủ đề phục vụ, khác kiểm định dạng hoặc bằng chứng.',kind='scenario',context='Input hợp lệ về độ dài/ngôn ngữ nhưng hỏi một chủ đề ngoài chức năng sản phẩm.')
item(d,44,'Vì sao phòng thủ prompt injection không nên chỉ dựa vào regex/classifier detection?', ['Biến thể mới có thể bypass; cần giới hạn cả năng lực/hành động agent được phép làm','Có detector thì không còn cần tách dữ liệu khỏi chỉ dẫn','Detection đã đúng trên test set thì mọi kênh tool mới có thể được tin mặc định'],'a','Lọc nội dung không thay thế ranh giới quyền và kiến trúc giới hạn thiệt hại.')
item(d,45,'Spotlighting giúp giảm indirect injection bằng cơ chế nào?', ['Đánh dấu/tách nội dung là data để không coi nó như instruction','Nâng thẩm quyền mọi retrieved document lên bằng system policy','Xóa ranh giới context/instruction để model tự chọn nguồn đáng tin'],'a','Delimiting/datamarking giúp phân biệt dữ liệu không tin cậy với lệnh có thẩm quyền.')
item(d,53,'Một quy trình red teaming có ích cần nối việc phát hiện lỗ hổng với bước nào?', ['Ghi kết quả, sửa và kiểm thử lại; đưa ca tấn công vào regression suite','Chỉ đếm số prompt bị từ chối trong một demo','Thay prompt tấn công bằng happy path để kết quả cuối dễ so hơn'],'a','Adversarial tests tạo bằng chứng và regression checks, không chỉ danh sách exploit.')
item(d,58,'Human-as-tiebreaker đặt quyền quyết định cuối ở đâu?', ['Con người quyết định, agent hỗ trợ cho tình huống high-stakes','Agent thực hiện trước rồi con người chỉ review sau','Agent tự duyệt nếu score vượt threshold nội bộ'],'a','Mức này khác on-the-loop review sau và in-the-loop approve trước đề xuất của agent.')
item(d,62,'Vì sao màn duyệt chỉ có hai nút Approve/Reject nhưng không có context dễ trở thành rubber stamp?', ['Người duyệt thiếu căn cứ hiểu hành động và hậu quả nên khó phán đoán thực chất','Hai nút luôn là thiết kế không thể dùng trong bất kỳ approval flow nào','Có người bấm duyệt tự động suy ra quyết định đã được kiểm chứng'],'a','Hiệu quả phụ thuộc thông tin phục vụ quyết định, không chỉ sự tồn tại của thao tác duyệt.')
item(d,67,'Một node gửi email rồi gọi interrupt(). Khi resume node chạy lại từ đầu, thiết kế nào tránh gửi lặp?', ['Đưa approval trước side effect hoặc tách side effect sang node sau approval','Giữ thứ tự cũ vì checkpoint tự nhận biết mọi email đã gửi','Chỉ thêm một dòng prompt dặn model đừng gửi email lần hai'],'a','Resume có thể chạy lại code của node; boundary side effect phải được đặt an toàn.',kind='scenario',context='Agent tạm dừng chờ người duyệt và sau đó được tiếp tục từ checkpoint.')
item(d,70,'Approval hết hạn mà chưa có người xử lý nên được coi thế nào trong fail-closed flow?', ['Mặc định từ chối hoặc escalation, không tự approve','Mặc định approve vì không ai phản đối','Xóa dấu vết yêu cầu rồi thử write lại không qua gate'],'a','Durable timer cần một đường kết thúc an toàn khi chờ duyệt quá hạn.')
item(d,72,'Những nội dung nào làm escalation có đủ căn cứ ra quyết định? (Chọn tất cả đáp án đúng.)',['Hành động cụ thể và lý do cần hỏi','Bằng chứng, rủi ro và lựa chọn duyệt/từ chối/sửa','Chỉ một confidence score thay cho mô tả hành động','Chỉ liên kết tới homepage rồi để người duyệt tự tìm bằng chứng'],['a','b'],'Đưa evidence và hậu quả ngay trong màn duyệt giảm gánh nặng tìm kiếm/nguy cơ duyệt mù.',kind='multiple_choice')
item(d,75,'Những dữ kiện nào nên nằm trong audit trail của quyết định HITL? (Chọn tất cả đáp án đúng.)',['Trace ID, hành động đề xuất và evidence','Người duyệt, thời điểm và quyết định; bản trước/sau nếu có sửa','Chỉ tổng approve/reject mỗi tháng, không liên kết run','Ghi đè các quyết định cũ bằng quyết định mới để chỉ giữ trạng thái cuối'],['a','b'],'Audit append-only liên kết đề xuất, căn cứ và người quyết định để replay/điều tra/cải thiện.',kind='multiple_choice')
item(d,78,'Automation bias kiểu commission khác omission thế nào?', ['Commission làm theo gợi ý sai dù có bằng chứng ngược; omission bỏ sót khi máy không báo','Commission là máy không cảnh báo; omission là làm theo cảnh báo sai','Hai kiểu đều chỉ có nghĩa model suy luận sai, không liên quan người giám sát'],'a','Phân biệt này chỉ ra cơ chế con người dùng máy như lối tắt thay cho tự kiểm chứng.')
item(d,85,'Một chatbot củng cố khuôn mẫu nghề nghiệp theo giới dù không phân bổ khoản vay hay việc làm đang tạo loại harm nào?', ['Representational harm','Chỉ allocative harm vì mọi bias đều phân bổ nguồn lực','Chỉ lỗi availability của hệ thống'],'a','Representational harm có thể tồn tại qua mô tả/khuôn mẫu ngay cả khi không phân bổ cơ hội.',kind='scenario',context='Sản phẩm trả lời mô tả các nhóm người theo định kiến lặp lại.')
