item(d,26,'Với tác vụ dài hơn một request thông thường, submit-and-poll tách việc nhận và xử lý thế nào?', ['API trả job_id sớm, worker chạy và client lấy kết quả sau','Giữ HTTP request mở nhưng không gửi dữ liệu tới khi mọi việc xong','Chạy lại toàn bộ tác vụ mỗi lần client poll để có kết quả mới'],'a','Job queue/worker giữ công việc ngoài vòng request-response ngắn.')
item(d,28,'Một hàm async def chứa blocking I/O vẫn có thể gây vấn đề nào?', ['Chặn event loop, làm các request cùng worker bị nghẽn','Tự được chuyển sang background worker nên không ảnh hưởng concurrency','Chỉ chậm request đó, không thể tác động request khác'],'a','Async có hiệu quả khi await I/O không block; khai báo async không tự biến code blocking thành non-blocking.')
item(d,31,'Vì sao không đặt provider API key trong biến NEXT_PUBLIC_/VITE_ của frontend?', ['Build có thể nhúng key vào JS bundle phía browser, nên cần backend proxy giữ secret','Tên biến public chỉ là quy ước, bundle tự mã hóa key bằng quyền backend','Browser gọi provider trực tiếp sẽ tự che key khỏi người dùng cuối'],'a','Client-side UI không đồng nghĩa keyless; secret phải nằm phía server khi dùng hosted provider.')
item(d,58,'Spend alert và pre-call admission control khác nhau về tác dụng thế nào?', ['Alert thông báo sau sự kiện; admission control kiểm budget trước và có thể từ chối call','Alert tự chặn mọi request ngay khi chạm ngưỡng nên không cần enforcement','Admission control chỉ ghi log sau khi call hoàn tất'],'a','Bảo vệ chi phí cần kiểm trước request, không nhầm thông báo với hard cap.')
item(d,63,'CPU thấp nhưng nhiều request đang chờ LLM. Autoscaling nên ưu tiên tín hiệu nào?', ['Concurrency hoặc queue depth','Chỉ CPU utilization','Chỉ số container image tags đã phát hành'],'a','Agent I/O-bound có thể bão hòa request capacity dù CPU không cao.',kind='scenario',context='Instance giữ nhiều request dài, thời gian chờ và backlog tăng nhưng CPU vẫn thấp.')
item(d,64,'Readiness failure khác liveness failure ở phản ứng vận hành nào?', ['Readiness ngắt traffic khỏi load balancer; liveness có thể restart container','Readiness luôn restart; liveness chỉ gỡ traffic','Cả hai đều nên restart ngay khi dependency chậm tạm thời'],'a','Phân biệt khả năng nhận việc với tiến trình còn sống giúp tránh restart loop vô ích.')
item(d,65,'Graceful shutdown của một agent turn dài cần làm gì sau khi ngừng nhận traffic mới?', ['Drain các request đang chạy trước khi dừng, với grace period phù hợp','Kill worker ngay sau SIGTERM để cân bằng tải nhanh','Route request đang chạy sang instance mới nhưng bỏ state tiến độ'],'a','Agent turn có thể dài; cắt worker sớm gây mất request hoặc side effect chưa được xử lý rõ.')
item(d,67,'Prompt cache và semantic response cache khác nhau ở thứ được tái sử dụng thế nào?', ['Prompt cache tái dùng prefix computation; semantic cache tái dùng câu trả lời cho query tương tự','Cả hai chỉ lưu final answer theo exact bytes của query','Semantic cache chỉ chia sẻ KV prefix, không có rủi ro stale answer'],'a','Response cache bỏ call lặp nhưng phải xử lý freshness, khác caching phần tính prefix của model.')
item(d,79,'Shadow traffic của agent cần chặn side effect vì sao dù không đưa output tới user?', ['Bản shadow vẫn có thể gửi mail/ghi dữ liệu/trừ tiền nếu tool được thực thi thật','Output không hiển thị tự động ngăn mọi tool call','Chỉ canary mới có khả năng tạo write action, shadow thì không'],'a','Không trả answer không đồng nghĩa không có tác động lên hệ ngoài.')
item(d,80,'Vì sao rollback prompt/model có thể không cần một lần deploy container mới?', ['Prompt/model config có vòng đời riêng và có thể chuyển label về bản trước','Mọi prompt thay đổi đều được tự động cập nhật trong image cũ','Rollback luôn chỉ là thay tag image dù lỗi nằm ở prompt registry'],'a','Tách artifact cấu hình bất biến và label di động cho phép rollback độc lập với code image.')
item(d,85,'Vì sao hash raw arguments có thể chưa đủ để deduplicate ý định write của LLM agent?', ['Cùng ý định có thể được model biểu diễn bằng args khác bytes; cần key ổn định theo hành động nghiệp vụ','Các arguments khác bytes luôn là hai ý định hoàn toàn khác','Mỗi lần retry nên sinh idempotency key mới để bảo đảm thực thi'],'a','Key ổn định như order_id cần gắn intent/action, không chỉ ngẫu nhiên theo chuỗi model sinh.')
item(d,86,'Journal-and-replay giảm chi phí/rủi ro sau crash bằng cách nào?', ['Đọc lại output/decision đã ghi thay vì gọi lại model và lặp bước đã hoàn tất','Gọi lại toàn bộ model/tool từ đầu để tạo câu trả lời giống nhất','Chỉ lưu final answer, bỏ mọi bước trung gian đã có side effect'],'a','Memoize/replay các quyết định giảm nondeterministic re-execution; hệ ngoài vẫn cần idempotency.')
item(d,90,'Per-agent identity và token scope hẹp cải thiện gì so với một god-key chung?', ['Giới hạn quyền/tác động mỗi agent và giảm việc lạm dụng quyền thay agent khác','Mọi agent tự kế thừa toàn quyền của supervisor để giảm kiểm tra','Một lần login của bất kỳ agent nào cấp quyền vô hạn cho toàn graph'],'a','Least privilege cần danh tính/scope phù hợp task, không chia sẻ credential có quyền quá rộng.')
